{
  "chapter_index": 2,
  "name": "The Court of Scholars and the Silent Sword / সভা ও শাণিত কৃপাণ",
  "chapter_title": "গৌড়ের রাজসভা ও রণহুঙ্কার",
  "book_name": "LAXMANSEN",
  "book_long_title": "কনৌজ বিজয়: বাংলার গৌরবময় অধ্যায় – বল্লাল সেন ও লক্ষ্মণ সেনের অমর কাহিনি",
  "chapter_summary": "নবদ্বীপের রাজসভায় বল্লাল সেন যখন কৌলিন্য প্রথা ও শাস্ত্রচর্চায় মগ্ন, লক্ষ্মণ সেন তখন বাংলার সামরিক শক্তি পুনর্গঠনে ব্যস্ত। একদিকে মসলিন ও লবণের বাণিজ্যে বাংলার সমৃদ্ধি, অন্যদিকে প্রতিবেশী রাজ্যগুলোর ঈর্ষা—এই টানাপোড়েনের মধ্যে তরুণ রাজপুত্র তাঁর নিজস্ব গোয়েন্দা বাহিনী ও আধুনিক অস্ত্রাগার গড়ে তুলছেন।",
  "chapter_segments": [
    {
      "segment_index": 1,
      "name": "initial_spark",
      "segment_title": "গৌড়ীয় আভিজাত্যের মধ্যাহ্ন",
      "segment_seed": "নবদ্বীপের রাজসভা আজ জয়দেব ও ধোয়ীর কাব্যপাঠে মুখরিত। মহারাজ বল্লাল সেন সিংহাসনে উপবিষ্ট, তাঁর সম্মুখে রত্নখচিত থালায় রাখা আছে কাপর্দক পুরাণ বা কড়ি মুদ্রা। আভিজাত্য আর শাস্ত্রীয় অনুশাসনের এক অপূর্ব মিলনস্থল এই গৌড়।"
    },
    {
      "segment_index": 2,
      "name": "growing_affection",
      "segment_title": "কৌলিন্যের নতুন নিয়ম",
      "segment_seed": "বল্লাল সেন ঘোষণা করেন কৌলিন্য প্রথা। ব্রাহ্মণ ও কায়স্থদের মধ্যে শ্রেষ্ঠত্ব নির্ধারণের নতুন মানদণ্ড নিয়ে রাজসভায় গুঞ্জন ওঠে। হলায়ুধ মিশ্রের শাস্ত্রীয় সমর্থনে রাজা আনন্দিত হলেও যুবরাজ লক্ষ্মণের চোখে মুখে ফুটে ওঠে ভিন্ন এক প্রশ্ন।"
    },
    {
      "segment_index": 3,
      "name": "internal_struggle",
      "segment_title": "জন্ম বনাম বীরত্ব",
      "segment_seed": "রাজপ্রাসাদের চিত্রশালায় দাঁড়িয়ে লক্ষ্মণ সেন তাঁর পিতামহ বিজয় সেনের প্রতিকৃতির দিকে তাকিয়ে থাকেন। তিনি মনে মনে ভাবেন—কূলের আভিজাত্য কি কোনো ভীরুকে রক্ষা করতে পারে? তাঁর কাছে রক্তের শুদ্ধির চেয়ে তরবারির ধারের গুরুত্ব অনেক বেশি।"
    },
    {
      "segment_index": 4,
      "name": "external_obstacle",
      "segment_title": "তাম্রলিপ্তের স্বর্ণালি হাতছানি",
      "segment_seed": "তাম্রলিপ্ত বন্দর থেকে বণিকরা খবর নিয়ে আসে। বাংলার মসলিন আর লবণের কদর বিশ্বজুড়ে, কিন্তু সেই সম্পদের লোভ সামলাতে পারছে না আর্যাবর্তের অন্যান্য রাজারা। বাণিজ্যের সুরক্ষা নিয়ে সেন রাজসভায় উদ্বেগ বৃদ্ধি পায়।"
    },
    {
      "segment_index": 5,
      "name": "confession_of_love",
      "segment_title": "মাতৃভূমির প্রতি প্রতিজ্ঞা",
      "segment_seed": "নিভৃত অরণ্যে নিজের গোপন গোয়েন্দা বাহিনীর সাথে মিলিত হন লক্ষ্মণ। তিনি ঘোষণা করেন, তাঁর প্রথম এবং একমাত্র প্রেম এই বাংলার মাটি। তিনি শপথ করেন, কনৌজ থেকে কামরূপ পর্যন্ত সেন সাম্রাজ্যের বিজয়কেতন উড়িয়ে তবেই তিনি শান্ত হবেন।"
    },
    {
      "segment_index": 6,
      "name": "intimate_moment",
      "segment_title": "অস্ত্রাগারের নিস্তব্ধতা",
      "segment_seed": "গভীর রাতে লক্ষ্মণ সেন অস্ত্রাগারে নতুন ধরনের বর্ম পরীক্ষা করেন। সেখানে কোনো চাটুকার নেই, কেবল আছে আগুনের উত্তাপ আর হাতুড়ির শব্দ। নিজের তৈরি করা এই নতুন সামরিক কৌশলের সাথে তিনি একাত্ম হয়ে ওঠেন।"
    },
    {
      "segment_index": 7,
      "name": "reaffirmation_of_bond",
      "segment_title": "পিতা-পুত্রের নীরব বোঝাপড়া",
      "segment_seed": "গভীর রাতে বল্লাল সেন যজ্ঞ শেষে পুত্রের কক্ষে আসেন। তিনি লক্ষ্মণের চোখে যুদ্ধের আগুন দেখেন। যদিও তাঁদের পথ আলাদা, তবু বাংলার সুরক্ষায় পিতার আশীর্বাদ পুত্রের মাথার ওপর নীরবে নেমে আসে।"
    },
    {
      "segment_index": 8,
      "name": "bittersweet_memory",
      "segment_title": "বিজয় সেনের উত্তরাধিকার",
      "segment_seed": "পুরানো দলিলে লক্ষ্মণ দেখেন কীভাবে বিজয় সেন হিমালয়ের পাদদেশ পর্যন্ত পৌঁছেছিলেন। সেই গৌরবময় অতীত ফিরে পাওয়ার নেশায় যুবরাজ তাঁর গোপ্তচরদের নির্দেশ দেন কনৌজের রাজনৈতিক দুর্বলতা খুঁজে বের করার জন্য।"
    }
  ],
