  "chapter_summary": "১২০৪ খ্রিস্টাব্দের এক দুপুরে, বখতিয়ার খলজির অতর্কিত আক্রমণ নবদ্বীপকে স্তম্ভিত করে দেয়। মাত্র কয়েকজন অশ্বারোহী নিয়ে ঘোড়া বিক্রেতার ছদ্মবেশে এসে তারা অতর্কিতে হামলা চালায়। বিশৃঙ্খলার মধ্যে যুবরাজ লক্ষ্মণ সেন কৌশলগতভাবে পশ্চাদপসরণ করেন, পূর্ববঙ্গের দিকে রওনা দেন শক্তি সঞ্চয়ের আশায়।",
  "chapter_segments": [
    {
      "segment_index": 1,
      "name": "segment-1",
      "segment_title": "মধ্যাহ্নের নিস্তব্ধতা ভঙ্গ",
      "segment_seed": "১২০৪ খ্রিস্টাব্দের এক অলস দুপুর। নবদ্বীপ নগরী মধ্যাহ্নভোজের পর এক গভীর ঘুমে আচ্ছন্ন। প্রাসাদ থেকে শুরু করে সাধারণ কুটির পর্যন্ত সর্বত্র এক প্রশান্ত নিস্তব্ধতা। কিন্তু এই নিস্তব্ধতা ছিল এক আসন্ন ঝড়ের পূর্বাভাস।",
      "engagement": "tender_anticipation"
    },
    {
      "segment_index": 2,
      "name": "segment-2",
      "segment_title": "ছদ্মবেশী অশ্বারোহী",
