{
  "chapter_index": 1,
  "name": "The Dawn of Ambition / উচ্চাকাঙ্ক্ষার উদয়",
  "chapter_title": "সিংহাসনের ছায়া",
  "book_name": "LAXMANSEN",
  "book_long_title": "কনৌজ বিজয়: বাংলার গৌরবময় অধ্যায় – বল্লাল সেন ও লক্ষ্মণ সেনের অমর কাহিনি",
  "chapter_summary": "একাদশ শতাব্দীর শেষভাগ। বল্লাল সেন গৌড়ের সিংহাসনে আসীন। তিনি যখন সমাজ সংস্কার ও শাস্ত্রীয় সাহিত্য সাধনায় মগ্ন, তরুণ রাজপুত্র লক্ষ্মণ সেন তখন সামরিক শক্তিতে আর্যাবর্ত জয়ের স্বপ্ন দেখছেন। পিতা ও পুত্রের এই আদর্শগত সংঘাত এবং আসন্ন যুদ্ধের দামামায় সেন সাম্রাজ্যের এক নতুন অধ্যায় শুরু হতে চলেছে।",
  "chapter_segments": [
    {
      "segment_index": 1,
      "name": "setting_the_scene",
      "segment_title": "গঙ্গার তীরে সন্ধ্যার আলোকচ্ছটা",
      "segment_seed": "নবদ্বীপের গঙ্গার ঘাটে তখন গোধূলি বেলার মায়াবী আলো। রাজপ্রাসাদের সুউচ্চ মিনার থেকে ভেসে আসছে সন্ধ্যারতির শঙ্খধ্বনি। ধূপ আর অগুরুর সুগন্ধে চারদিক আমোদিত। গঙ্গার শান্ত সলিল বাংলার সমৃদ্ধির সাক্ষী হয়ে বইছে।"
    },
    {
      "segment_index": 2,
      "name": "status_quo_description",
      "segment_title": "বল্লাল সেনের শাস্ত্রীয় গৌড়",
      "segment_seed": "মহারাজ বল্লাল সেন তাঁর প্রশস্ত শাস্ত্রকক্ষে তালপাতার পুঁথিতে মগ্ন। তিনি 'দানসাগর' ও 'অদ্ভুতসাগর' রচনায় রত। তাঁর রাজসভা কবি আর পণ্ডিতদের তর্কে মুখরিত। রাজা বিশ্বাস করেন, সুসংহত সমাজ সংস্কার আর আভিজাত্যই সাম্রাজ্যের মূল ভিত্তি।"
    },
    {
      "segment_index": 3,
      "name": "character_debut",
      "segment_title": "যুবরাজ লক্ষ্মণ ও উত্তর ভারতের মানচিত্র",
      "segment_seed": "প্রাসাদের অন্য প্রান্তে এক কক্ষ। প্রদীপের আলোয় একা যুবরাজ লক্ষ্মণ সেন। তাঁর সামনে রাখা এক বিশাল চর্মপত্র—উত্তর ভারতের মানচিত্র। তাঁর হাত স্থির হয়ে আছে কনৌজের ওপর। তাঁর চোখে শাস্ত্রের শান্তি নয়, বরং রণক্ষেত্রের তৃষ্ণা।"
    },
    {
      "segment_index": 4,
      "name": "initial_mystery",
      "segment_title": "সীমান্তের রক্তিম বার্তা",
      "segment_seed": "হঠাৎ অলিন্দে দ্রুত পদধ্বনি। এক রক্তাক্ত দূত এসে খবর দিল, পশ্চিম সীমান্তে কিছু অজ্ঞাতপরিচয় দস্যু হানা দিয়েছে। গ্রাম পুড়ছে। বল্লাল সেন একে সাময়িক অরাজকতা ভাবলেও লক্ষ্মণের দৃষ্টিতে এটি এক মহাপ্রলয়ের ইঙ্গিত।"
    },
    {
      "segment_index": 5,
